1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { useTheme } from "next-themes";
7	import { cn } from "@repo/ui/lib/utils";
8	import {
9	  ChevronDown, ChevronRight, LayoutDashboard, AlertTriangle, Building2,
10	  Users, Wrench, FileText, MessageSquareText, Sparkles, Home,
11	  PanelLeftClose, PanelLeftOpen, Sun, Moon, RotateCcw, Loader2, Zap,
12	} from "lucide-react";
13	import { api } from "@/lib/api";
14	import { subscribe } from "@/lib/bus";
15	import { useToastSafe } from "@/components/toaster";
16	import { useAutoSolve } from "@/lib/auto-solve-context";
17	import type { Property } from "@/lib/types";
18	
19	const PROP_TABS = [
20	  ["tickets",  "Tickets"],
21	  ["units",    "Units & Owners"],
22	  ["context",  "Context"],
23	  ["editor",   "Editor"],
24	  ["versions", "Versions"],
25	  ["sources",  "Sources"],
26	  ["policies", "Policies"],
27	  ["calls",    "Calls"],
28	] as const;
29	
30	export function Sidebar() {
31	  const pathname = usePathname();
32	  const [collapsed, setCollapsed] = useState(false);
33	  const [openProps, setOpenProps] = useState<Record<string, boolean>>({ p1: true });
34	  const [properties, setProperties] = useState<Property[]>([]);
35	  const { theme, setTheme } = useTheme();
36	  const [mounted, setMounted] = useState(false);
37	  useEffect(() => setMounted(true), []);
38	
39	  // Demo reset state
40	  const [showResetConfirm, setShowResetConfirm] = useState(false);
41	  const [resetting, setResetting] = useState(false);
42	  const toast = useToastSafe();
43	
44	  // Auto-Solve toggle (Sprint 3)
45	  const { autoSolve, queueStatus, isToggling, enable, disable } = useAutoSolve();
46	  const [showAutoSolveConfirm, setShowAutoSolveConfirm] = useState(false);
47	
48	  useEffect(() => {
49	    let cancelled = false;
50	    const refresh = () =>
51	      api.properties.list()
52	        .then((list) => { if (!cancelled) setProperties(list); })
53	        .catch(() => { /* silently leave list empty */ });
54	    refresh();
55	    const unsub = subscribe((event) => {
56	      if (event.kind === "context-bumped" || event.kind === "ticket-changed") refresh();
57	    });
58	    return () => { cancelled = true; unsub(); };
59	  }, []);
60	
61	  const activePropId = pathname.match(/^\/property\/([^/]+)/)?.[1] ?? null;
62	  const activeProp = activePropId ? properties.find((p) => p.id === activePropId) ?? null : null;
63	
64	  async function handleAutoSolveToggle() {
65	    if (autoSolve) {
66	      try {
67	        await disable();
68	        toast.push({
69	          title: "Auto-Solve stopped",
70	          description: "The agent will finish the current ticket and then stop.",
71	          variant: "default",
72	        });
73	      } catch (err) {
74	        toast.push({
75	          title: "Failed to stop",
76	          description: err instanceof Error ? err.message : "Unknown error",
77	          variant: "destructive",
78	        });
79	      }
80	    } else {
81	      setShowAutoSolveConfirm(true);
82	    }
83	  }
84	
85	  async function handleAutoSolveConfirm() {
86	    setShowAutoSolveConfirm(false);
87	    try {
88	      await enable();
89	      toast.push({
90	        title: "Auto-Solve activated",
91	        description: "Hermes is now processing tickets autonomously.",
92	        variant: "success",
93	      });
94	    } catch (err) {
95	      toast.push({
96	        title: "Failed to start",
97	        description: err instanceof Error ? err.message : "Unknown error",
98	        variant: "destructive",
99	      });
100	    }
101	  }
102	
103	  async function handleReset() {
104	    setShowResetConfirm(false);
105	    setResetting(true);
106	    try {
107	      await api.dev.reset();
108	      toast.push({
109	        title: "Demo zurückgesetzt",
110	        description: "Alle Tickets und Daten wurden auf den Demo-Ausgangszustand zurückgesetzt.",
111	        variant: "success",
112	      });
113	      // Hard-redirect to overview so all client state (sidebar counts,
114	      // cached queries) is fully wiped — avoids the router.refresh() race
115	      // condition where refresh fires against the current route, not /overview.
116	      window.location.href = "/overview";
117	    } catch (err) {
118	      toast.push({
119	        title: "Reset fehlgeschlagen",
120	        description: err instanceof Error ? err.message : "Unbekannter Fehler beim Zurücksetzen.",
121	        variant: "destructive",
122	      });
123	    } finally {
124	      setResetting(false);
125	    }
126	  }
127	
128	  return (
129	    <>
130	      <aside
131	        className={cn(
132	          "flex h-full shrink-0 flex-col border-r bg-background transition-all duration-200",
133	          collapsed ? "w-14" : "w-64"
134	        )}
135	      >
136	        {/* Header */}
137	        <div className="flex h-14 items-center justify-between border-b px-3">
138	          {!collapsed && (
139	            <div className="flex items-center gap-2 min-w-0">
140	              <div className="grid h-7 w-7 shrink-0 place-items-center rounded-md bg-foreground text-background">
141	                <Sparkles className="h-4 w-4" />
142	              </div>
143	              <div className="flex flex-col leading-tight min-w-0">
144	                <span className="text-sm font-semibold">Buena</span>
145	                <span className="text-[10px] uppercase tracking-wider text-muted-foreground">Context Engine</span>
146	              </div>
147	            </div>
148	          )}
149	          {collapsed && (
150	            <div className="mx-auto grid h-7 w-7 place-items-center rounded-md bg-foreground text-background">
151	              <Sparkles className="h-4 w-4" />
152	            </div>
153	          )}
154	          {!collapsed && (
155	            <button
156	              onClick={() => setCollapsed(true)}
157	              className="ml-2 rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
158	              title="Collapse sidebar"
159	            >
160	              <PanelLeftClose className="h-4 w-4" />
161	            </button>
162	          )}
163	        </div>
164	
165	        {/* Demo Mode Banner (visible when expanded) */}
166	        {!collapsed && (
167	          <div className="flex items-center gap-1.5 border-b bg-amber-500/10 px-3 py-1.5">
168	            <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500 animate-pulse" />
169	            <span className="text-[10px] font-semibold uppercase tracking-wider text-amber-600 dark:text-amber-400">
170	              Demo Mode
171	            </span>
172	          </div>
173	        )}
174	
175	        {/* Expand button when collapsed */}
176	        {collapsed && (
177	          <button
178	            onClick={() => setCollapsed(false)}
179	            className="mx-auto mt-3 rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground"
180	            title="Expand sidebar"
181	          >
182	            <PanelLeftOpen className="h-4 w-4" />
183	          </button>
184	        )}
185	
186	        {/* Collapsed demo mode dot */}
187	        {collapsed && (
188	          <div
189	            className="mx-auto mt-1 h-1.5 w-1.5 rounded-full bg-amber-500"
190	            title="Demo Mode"
191	          />
192	        )}
193	
194	        {/* Nav */}
195	        <nav className={cn("flex-1 overflow-y-auto p-2 text-sm", collapsed && "overflow-hidden")}>
196	          {!collapsed ? (
197	            <>
198	              <Zone label="Work">
199	                <Item href="/overview"    icon={LayoutDashboard} active={pathname === "/overview"}>Overview</Item>
200	                <Item href="/escalations" icon={AlertTriangle}   active={pathname === "/escalations"}>Escalations</Item>
201	              </Zone>
202	
203	              <Zone label="Properties">
204	                {properties.map((p) => {
205	                  const open = openProps[p.id];
206	                  const inThisProp = pathname.startsWith(`/property/${p.id}`);
207	                  return (
208	                    <div key={p.id}>
209	                      <button
210	                        onClick={() => setOpenProps((s) => ({ ...s, [p.id]: !s[p.id] }))}
211	                        className={cn(
212	                          "flex w-full items-center justify-between gap-2 rounded-md px-2 py-1.5 hover:bg-accent",
213	                          inThisProp && "bg-accent"
214	                        )}
215	                      >
216	                        <span className="flex items-center gap-2 truncate text-sm">
217	                          <Home className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
218	                          <span className="truncate">{p.name}</span>
219	                        </span>
220	                        <span className="flex shrink-0 items-center gap-1.5">
221	                          {p.openTickets > 0 && (
222	                            <span className="rounded-full bg-amber-500/20 px-1.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
223	                              {p.openTickets}
224	                            </span>
225	                          )}
226	                          {open ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
227	                        </span>
228	                      </button>
229	                      {open && (
230	                        <div className="ml-5 mt-0.5 border-l pl-2">
231	                          {PROP_TABS.map(([slug, label]) => {
232	                            const href = `/property/${p.id}/${slug}`;
233	                            return (
234	                              <Link
235	                                key={slug}
236	                                href={href}
237	                                className={cn(
238	                                  "block rounded-md px-2 py-1 text-[13px] text-muted-foreground hover:bg-accent hover:text-foreground",
239	                                  pathname === href && "bg-accent text-foreground font-medium"
240	                                )}
241	                              >
242	                                {label}
243	                              </Link>
244	                            );
245	                          })}
246	                        </div>
247	                      )}
248	                    </div>
249	                  );
250	                })}
251	              </Zone>
252	
253	              <Zone label="Knowledge">
254	                <Item href="/vendors"   icon={Wrench}    active={pathname.startsWith("/vendors") || pathname.startsWith("/vendor/")}>Vendors</Item>
255	                <Item href="/owners"    icon={Users}     active={pathname.startsWith("/owners") || pathname.startsWith("/owner/")}>Owners</Item>
256	                <Item href="/buildings" icon={Building2} active={pathname.startsWith("/buildings") || pathname.startsWith("/building/")}>Buildings</Item>
257	              </Zone>
258	
259	              <Zone label="Tools">
260	                <Item href="/extract" icon={FileText}          active={pathname === "/extract"}>PDF Extract</Item>
261	                <Item href="/chat"    icon={MessageSquareText} active={pathname === "/chat"}>Hermes Chat</Item>
262	              </Zone>
263	            </>
264	          ) : (
265	            /* Icon-only mode */
266	            <div className="mt-1 flex flex-col items-center gap-1">
267	              {[
268	                { href: "/overview",    icon: LayoutDashboard,  label: "Overview" },
269	                { href: "/escalations", icon: AlertTriangle,    label: "Escalations" },
270	                { href: "/vendors",     icon: Wrench,           label: "Vendors" },
271	                { href: "/owners",      icon: Users,            label: "Owners" },
272	                { href: "/buildings",   icon: Building2,        label: "Buildings" },
273	                { href: "/extract",     icon: FileText,         label: "PDF Extract" },
274	                { href: "/chat",        icon: MessageSquareText, label: "Hermes Chat" },
275	              ].map(({ href, icon: Icon, label }) => (
276	                <Link
277	                  key={href}
278	                  href={href}
279	                  title={label}
280	                  className={cn(
281	                    "rounded-md p-2 text-muted-foreground hover:bg-accent hover:text-foreground",
282	                    pathname.startsWith(href) && href !== "/" && "bg-accent text-foreground"
283	                  )}
284	                >
285	                  <Icon className="h-4 w-4" />
286	                </Link>
287	              ))}
288	            </div>
289	          )}
290	        </nav>
291	
292	        {/* Footer */}
293	        <div className={cn("border-t p-3", collapsed && "flex flex-col items-center gap-2 px-0")}>
