295	          <button
296	            onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
297	            className="flex items-center gap-2 rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground"
298	            title="Toggle theme"
299	            suppressHydrationWarning
300	          >
301	            <span suppressHydrationWarning className="inline-flex h-3.5 w-3.5 items-center justify-center">
302	              {mounted ? (theme === "dark" ? <Sun className="h-3.5 w-3.5" /> : <Moon className="h-3.5 w-3.5" />) : null}
303	            </span>
304	            {!collapsed && <span className="text-[11px]">Toggle theme</span>}
305	          </button>
306	
307	          {/* Auto-Solve Toggle (Sprint 3) */}
