1	"use client";
2	
3	/**
4	 * overview-client.tsx  (Sprint 3, s3-f3)
5	 *
6	 * Client-side interactive layer for the overview page.
7	 * Polls the tickets + properties APIs every 2 seconds when the auto-solve
8	 * queue is active so the pipeline view updates without a page refresh.
9	 *
10	 * Also subscribes to the global bus for ticket-changed events (manual actions
11	 * trigger an immediate re-fetch without waiting for the next poll cycle).
12	 *
13	 * The "currently processing" ticket gets a pulsing ring indicator.
14	 */
15	
16	import { useEffect, useRef, useState } from "react";
17	import Link from "next/link";
18	import { cn } from "@repo/ui/lib/utils";
19	import { Card, CardContent } from "@repo/ui/components/card";
20	import { Badge } from "@repo/ui/components/badge";
21	import { RiskBadge } from "@/components/badges";
22	import { PageHeader } from "@/components/page-header";
23	import { Button } from "@repo/ui/components/button";
24	import { AlertTriangle, ArrowRight, Mail, Phone } from "lucide-react";
25	import { api } from "@/lib/api";
26	import { pipelineStages } from "@/lib/pipeline";
27	import { timeAgo, formatEur } from "@/lib/utils";
28	import { subscribe } from "@/lib/bus";
29	import { useAutoSolve } from "@/lib/auto-solve-context";
30	import type { Ticket, Property } from "@/lib/types";
31	
32	const POLL_INTERVAL_ACTIVE = 2000;   // 2s when agent is running
33	const POLL_INTERVAL_IDLE   = 10000;  // 10s otherwise
34	
35	export function OverviewClient({
36	  initialTickets,
37	  initialProperties,
38	}: {
39	  initialTickets: Ticket[];
40	  initialProperties: Property[];
41	}) {
42	  const [tickets, setTickets] = useState<Ticket[]>(initialTickets);
43	  const [properties, setProperties] = useState<Property[]>(initialProperties);
44	  const { autoSolve, queueStatus } = useAutoSolve();
45	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
46	
47	  const refresh = async () => {
48	    try {
49	      const [t, p] = await Promise.all([
50	        api.tickets.list(),
51	        api.properties.list(),
52	      ]);
53	      setTickets(t);
54	      setProperties(p);
55	    } catch {
56	      // silently ignore — stale data is better than crashing
57	    }
58	  };
59	
60	  // Polling loop
61	  useEffect(() => {
62	    let cancelled = false;
63	    const interval = autoSolve ? POLL_INTERVAL_ACTIVE : POLL_INTERVAL_IDLE;
64	
65	    const schedule = () => {
66	      timerRef.current = setTimeout(async () => {
67	        if (cancelled) return;
68	        await refresh();
69	        if (!cancelled) schedule();
70	      }, interval);
71	    };
72	
73	    schedule();
74	    return () => {
75	      cancelled = true;
76	      if (timerRef.current) clearTimeout(timerRef.current);
77	    };
78	  }, [autoSolve]);
79	
80	  // Also re-fetch immediately on bus events (e.g. manual approvals)
81	  useEffect(() => {
82	    const unsub = subscribe((event) => {
83	      if (event.kind === "ticket-changed" || event.kind === "queue-tick") {
84	        refresh();
85	      }
86	    });
87	    return unsub;
88	  }, []);
89	
90	  const unsolved = tickets.filter((t) => !["resolved", "rejected"].includes(t.status));
91	  const proposed = tickets.filter((t) => t.status === "proposed");
92	  const completed = tickets.filter((t) => t.status === "completed");
93	  const resolved7d = tickets.filter((t) => t.status === "resolved").length;
